    "difficulty": "Medium",
    "question": "A student titrates 25.0 cm³ of an unknown acid with 0.1 mol/L NaOH. The endpoint requires 30.0 cm³ of NaOH. Assuming a 1:1 mole ratio, what is the concentration of the acid?",
