    "domain": "Biology",
    "topic": "Plants and Photosynthesis",
    "difficulty": "Hard",
    "question": "A student investigates the effect of gibberellin on stem elongation in dwarf pea plants. Gibberellin treatment causes dwarf plants to grow to normal height. Which of the following correctly explains the mechanism?",
